function backupDate(value){return value&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleString():'Not verified';}
function renderBackups(){
  const linked=inventory.devices.filter(d=>acronisData.links.some(l=>l.node_id===d.id)).length;
  $('#backup-summary').innerHTML=`<div><span>Computers</span><strong>${inventory.devices.length}</strong></div><div><span>Linked to Acronis</span><strong>${linked}</strong></div><div><span>Need linking</span><strong>${inventory.devices.length-linked}</strong></div>`;
  setFilter('#backup-company',inventory.companies,'All companies');
  const query=$('#backup-search').value.toLowerCase(),company=$('#backup-company').value;
  const devices=inventory.devices.filter(d=>(!company||d.companyId===company)&&`${d.name} ${d.company}`.toLowerCase().includes(query));
  $('#acronis-computers').innerHTML=devices.map(d=>{
    const link=acronisData.links.find(l=>l.node_id===d.id),resource=acronisData.resources.find(r=>r.id===link?.resource_id),backup=acronisData.backupResults?.find(b=>b.resourceId===resource?.id),task=backup?.latestTask;
    let label=!link?'Not linked':!resource?'Resource unavailable':!task?'No verified task':task.state==='completed'&&task.result==='ok'?'Last task succeeded':task.state==='completed'?'Last task needs attention':'Task: '+task.state;
    if(acronisData.error)label='Status unavailable';
    const success=!acronisData.error&&task?.state==='completed'&&task?.result==='ok';
    return `<article class="backup-row"><span class="backup-drive-icon" aria-hidden="true">▤</span><div class="backup-row-content"><div class="backup-row-title"><strong>${escape(d.name)}</strong><span class="backup-badge ${success?'success':''}">${escape(label)}</span><span class="backup-type-badge">Acronis</span></div><p>${escape(d.company)} · Schedule: <strong>View in provider</strong></p><p class="muted">Last successful task: ${escape(backupDate(backup?.lastSuccessfulTaskAt))}</p></div><div class="backup-row-actions">${resource&&acronisData.consoleUrl?`<button data-backup-info="${escape(d.id)}">↶ Restore…</button>`:''}<button data-backup-info="${escape(d.id)}" title="View backup details">◷ Details</button><button data-acronis-link="${escape(d.id)}" ${acronisData.error||!acronisData.checkedAt?'disabled':''}>✎ ${link?'Edit link':'Link device'}</button>${link?`<button class="danger" data-backup-unlink="${escape(d.id)}">Remove link</button>`:''}</div></article>`;

  }).join('')||'<p class="empty">No matching computers.</p>';
  const allowed=['D332948D-A7A9-4E07-B76C-253DCF6E17FB','1B6CB334-6CB5-4760-AE3C-B96A973D5A99'];
  const tasks=acronisData.tasks.filter(t=>$('#backup-history-filter').value==='all'||allowed.includes(t.type.toUpperCase())).sort((a,b)=>(Date.parse(b.completedAt||b.startedAt)||0)-(Date.parse(a.completedAt||a.startedAt)||0));
  $('#acronis-tasks').innerHTML='<table><thead><tr><th>CUSTOMER</th><th>ACTIVITY</th><th>RESULT</th><th>COMPLETED</th></tr></thead><tbody>'+tasks.map(t=>`<tr><td>${escape(t.tenant)}</td><td>${escape(t.title)}</td><td>${escape(t.state==='completed'&&t.result==='ok'?'Succeeded':t.state+' / '+t.result)}</td><td>${escape(backupDate(t.completedAt))}</td></tr>`).join('')+'</tbody></table>'+(tasks.length?'':'<p class="empty">No matching activities returned.</p>');
  bind('[data-acronis-link]',b=>linkAcronis(b.dataset.acronisLink));
  bind('[data-backup-unlink]',b=>{const d=inventory.devices.find(d=>d.id===b.dataset.backupUnlink);showDialog(`<h2>Remove backup link</h2><p>Remove the SkyBase Acronis link for ${escape(d.name)}?</p><p class="muted">This leaves the provider’s backups, agent, and schedule in place.</p><p id="unlink-error" role="alert"></p><div class="actions"><button data-close>Cancel</button><button class="danger" id="confirm-backup-unlink">Remove link</button></div>`);$('#confirm-backup-unlink').onclick=async()=>{const button=$('#confirm-backup-unlink');button.disabled=true;try{await api('acronis-link',{nodeId:d.id,resourceId:''});$('#modal').close();await loadAcronis();}catch(error){$('#unlink-error').textContent=error.message;button.disabled=false;}};});

  bind('[data-backup-info]',b=>{const d=inventory.devices.find(d=>d.id===b.dataset.backupInfo),link=acronisData.links.find(l=>l.node_id===d.id),backup=acronisData.backupResults?.find(r=>r.resourceId===link?.resource_id);showDialog(`<h2>${escape(d.name)} backup</h2><p class="muted">${escape(d.company)}</p><p>Last successful backup task: ${escape(backupDate(backup?.lastSuccessfulTaskAt))}</p><p class="muted">${backup?.latestTask?'Only tasks with a unique Acronis resource reference are shown.':'No uniquely matched backup task has been returned for this computer.'}</p><p class="muted">To run a backup, edit its schedule, or restore files, open the Acronis console and select this computer.</p><div class="actions"><button data-close>Close</button>${acronisData.consoleUrl?`<a class="button-link primary" href="${escape(acronisData.consoleUrl)}" target="_blank" rel="noopener noreferrer">Manage in Acronis ↗</a>`:''}</div>`);});
}
const networkTypes={unknown:'Unknown',workstation:'Workstations',server:'Servers',printer:'Printers',phone:'Phones',network:'Network devices'};
let scriptCategory='All';
function renderScripts(){const query=$('#script-search').value.toLowerCase();const rows=scriptLibrary.filter(s=>(scriptCategory==='All'||s.category===scriptCategory)&&`${s.name} ${s.description} ${s.category}`.toLowerCase().includes(query));$('#script-count').textContent=scriptLibrary.length+' Scripts';$('#script-categories').innerHTML=['All',...new Set(scriptLibrary.map(s=>s.category))].map(category=>`<button data-script-category="${escape(category)}" class="${scriptCategory===category?'active':''}" aria-pressed="${scriptCategory===category}">${escape(category)}</button>`).join('');bind('[data-script-category]',b=>{scriptCategory=b.dataset.scriptCategory;renderScripts();});
 $('#script-list').innerHTML=rows.map(s=>`<article class="script-card"><div class="script-card-title"><h2>${escape(s.name)}</h2><span class="script-version">v1.0</span></div><div class="script-tags"><span>${escape(s.category)}</span><span>PowerShell</span></div><p>${escape(s.description)}</p><p class="script-effect">${escape(s.effect)}</p><small>by ${escape(s.author)}</small><div class="script-actions"><button data-script-view="${s.id}">〈/〉 View Code</button><button data-script-copy="${s.id}">▣ Copy</button><button data-script-download="${s.id}" class="script-download">⇩ Download</button></div></article>`).join('')||'<p class="empty">No scripts match your search.</p>';
 bind('[data-script-view]',b=>viewScript(b.dataset.scriptView));bind('[data-script-copy]',b=>copyScript(b.dataset.scriptCopy));bind('[data-script-download]',b=>downloadScript(b.dataset.scriptDownload));}
function viewScript(id){const s=scriptLibrary.find(s=>s.id===id);showDialog(`<h2>${escape(s.name)}</h2><p>${escape(s.description)}</p><p class="script-effect">${escape(s.effect)}</p><pre class="script-code" tabindex="0"><code>${escape(s.code)}</code></pre><p class="muted">Review and test on one computer before wider use. Downloading does not run this script or send it to an agent.</p><div class="actions"><button data-close>Close</button><button id="script-modal-copy">Copy code</button><button id="script-modal-download" class="script-download">Download .ps1</button></div>`);$('#script-modal-copy').onclick=()=>copyScript(id);$('#script-modal-download').onclick=()=>downloadScript(id);}
async function copyScript(id){const s=scriptLibrary.find(s=>s.id===id);try{await navigator.clipboard.writeText(s.code);$('#script-message').textContent=s.name+' copied to clipboard.';}catch{showDialog(`<h2>Copy script</h2><p>Clipboard access is unavailable. Select and copy the code below.</p><textarea id="script-copy-text" readonly rows="16">${escape(s.code)}</textarea><button data-close>Close</button>`);$('#script-copy-text').select();}}
function downloadScript(id){const s=scriptLibrary.find(s=>s.id===id),url=URL.createObjectURL(new Blob(['\uFEFF'+s.code.replace(/\r?\n/g,'\r\n')],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=s.filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#script-message').textContent=s.filename+' download requested. It has not been executed.';}
$('#script-search').oninput=renderScripts;

let directoryData={status:'empty',result:{}},directoryLoading=false,directoryStarting=false,directoryTimer,directoryTab='users';
function renderDirectorySelectors(){const select=$('#directory-company');let saved='';try{saved=localStorage.getItem('skybase-directory-company')||'';}catch{}const selected=select.value||saved||inventory.companies[0]?.id||'';select.innerHTML=options(inventory.companies,selected,'Select company');renderDirectoryAgents();}
function renderDirectoryAgents(){const select=$('#directory-agent'),agents=inventory.devices.filter(d=>d.companyId===$('#directory-company').value&&d.online&&d.windows);select.innerHTML=options(agents,select.value||agents[0]?.id||'','Select Windows directory agent');$('#directory-sync').disabled=directoryStarting||directoryData.status==='running'||!agents.length;}
async function loadDirectory(id=''){if(directoryLoading)return;clearTimeout(directoryTimer);directoryLoading=true;const company=$('#directory-company').value;try{const data=await api('active-directory'+(id?'?id='+encodeURIComponent(id):'?companyId='+encodeURIComponent(company)));if(company!==$('#directory-company').value)return;directoryData=data;renderDirectory();if(data.status==='running'&&page==='directory')directoryTimer=setTimeout(()=>loadDirectory(data.id),2000);}catch(error){$('#directory-status').textContent=error.message;}finally{directoryLoading=false;}}
function renderDirectory(){const result=directoryData.result||{},users=result.users||[],groups=result.groups||[],ous=result.ous||[];$('#directory-status').textContent=directoryData.status==='empty'?'No directory snapshot. Choose your company and directory agent, then sync.':directoryData.status==='running'?'Reading Active Directory from '+directoryData.source_name+'…':directoryData.status==='failed'?directoryData.error:`${result.domain} · Domain Controller: ${result.server} · Synced ${new Date(directoryData.at).toLocaleString()} · Read-only snapshot`;
 $('#directory-summary').innerHTML=[[users.length,'Total users','♙'],[users.filter(u=>u.enabled).length,'Active','✓'],[users.filter(u=>!u.enabled).length,'Disabled','▣'],[groups.length,'Groups','▦']].map(([count,label,icon])=>`<article class="panel"><span class="directory-stat-icon">${icon}</span><div><strong>${count}</strong><small>${label}</small></div></article>`).join('');
 $('#directory-tabs').innerHTML=[['users',users],['groups',groups],['ous',ous]].map(([key,rows])=>`<button data-directory-tab="${key}" class="${directoryTab===key?'primary':''}">${key==='ous'?'OUs':key==='users'?'Users':'Groups'} (${rows.length})</button>`).join('');bind('[data-directory-tab]',b=>{directoryTab=b.dataset.directoryTab;renderDirectory();});
 const query=$('#directory-search').value.toLowerCase(),rows=(result[directoryTab]||[]).filter(row=>Object.values(row).some(v=>String(v).toLowerCase().includes(query)));
 const heads=directoryTab==='users'?['User','Username','Department','Title','OU / Container','Status']:directoryTab==='groups'?['Group','Description','Scope','Category','Direct members','Directory path']:['OU','Description','Directory path'];
 $('#directory-table').innerHTML=`<table class="directory-table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${(directoryTab==='users'?[`<div class="directory-user"><span>${escape(row.name.slice(0,1).toUpperCase())}</span><div><strong>${escape(row.name)}</strong><small>${escape(row.email)}</small></div></div>`,escape(row.username),escape(row.department)||'—',escape(row.title)||'—',escape(row.dn.replace(/^(?:\\.|[^,])*,/,'')),`<span class="badge ${row.enabled?'':'offline'}">${row.enabled?'Active':'Disabled'}</span>`]:directoryTab==='groups'?[escape(row.name),escape(row.description)||'—',escape(row.scope),escape(row.category),`<button data-directory-members="${escape(row.id)}">${row.memberCount} · View</button>`,escape(row.dn)]:[escape(row.name),escape(row.description)||'—',escape(row.dn)]).map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${heads.length}">No matching directory records. Sync a domain to load real data.</td></tr>`}</tbody></table>`;
 bind('[data-directory-members]',b=>{const group=groups.find(g=>g.id===b.dataset.directoryMembers);showDialog(`<h2>${escape(group.name)} — direct members</h2><p class="muted">Nested group members are not expanded.</p><div class="directory-members">${group.members.map(m=>`<p>${escape(m)}</p>`).join('')||'<p>No direct members.</p>'}</div><button data-close>Close</button>`);});renderDirectoryAgents();}
$('#directory-company').onchange=()=>{try{localStorage.setItem('skybase-directory-company',$('#directory-company').value);}catch{}directoryData={status:'empty',result:{}};renderDirectory();loadDirectory();};$('#directory-search').oninput=renderDirectory;
$('#directory-sync').onclick=async()=>{directoryStarting=true;renderDirectoryAgents();$('#directory-status').textContent='Starting directory sync…';try{const response=await api('active-directory-sync',{companyId:$('#directory-company').value,nodeId:$('#directory-agent').value});await loadDirectory(response.id);}catch(error){$('#directory-status').textContent=error.message;}finally{directoryStarting=false;renderDirectoryAgents();}};

let networkData={status:'empty',result:[],labels:[]},networkLoading=false,networkStarting=false,networkTimer,networkFilter='all',networkMap=false;
function renderNetworkSites(){let selected=$('#network-site').value;try{if(!selected){const stored=localStorage.getItem('skybase-network-site');if(inventory.locations.some(l=>l.id===stored))selected=stored;}}catch{}$('#network-site').innerHTML=options(inventory.locations.map(l=>{const c=inventory.companies.find(c=>c.id===l.company_id);return {id:l.id,name:(c?.customer?c.customer+' / ':'')+(c?.name||'Company')+' / '+l.name};}),selected||inventory.locations[0]?.id||'','Select customer site');renderNetworkAgents();}
function renderNetworkAgents(){const selected=$('#network-agent').value;const agents=inventory.devices.filter(d=>d.locationId===$('#network-site').value&&d.online&&d.windows);$('#network-agent').innerHTML=options(agents,selected||agents[0]?.id||'','Select online Windows agent');$('#start-network-scan').disabled=networkStarting||networkData.status==='running'||!agents.length;}
function networkRows(){return (networkData.result||[]).map(d=>{const label=networkData.labels?.find(l=>l.ip===d.ip);const scannerType=d.scanner&&/windows/i.test(networkData.source_os||'')?(/server/i.test(networkData.source_os)?'server':'workstation'):'unknown';return {...d,type:label?.type||scannerType,name:label?.hostname||d.hostname||'Not reported',os:d.scanner?networkData.source_os:'Not verified'};}).sort((a,b)=>a.ip.split('.').reduce((n,v)=>n*256+Number(v),0)-b.ip.split('.').reduce((n,v)=>n*256+Number(v),0));}
async function loadNetwork(id=''){if(networkLoading)return;clearTimeout(networkTimer);networkLoading=true;const site=$('#network-site').value;try{const value=await api('network-scans'+(id?'?id='+encodeURIComponent(id):site?'?locationId='+encodeURIComponent(site):''));if(site!==$('#network-site').value)return;networkData=value;if(value.cidr&&!$('#network-cidr').value)$('#network-cidr').value=value.cidr;renderNetwork();if(value.status==='running'&&page==='network')networkTimer=setTimeout(()=>loadNetwork(value.id),2000);}catch(error){$('#network-message').textContent=error.message;}finally{networkLoading=false;}}
function renderNetwork(){const rows=networkRows();$('#network-found').textContent=rows.length+' found';$('#network-scan-status').textContent=networkData.status==='empty'?'No scan results for this site.':networkData.status==='running'?'Scanning from '+networkData.source_name+'… Results will appear when the scan completes.':networkData.status==='failed'?networkData.error:`${networkData.cidr} · Scanned from ${networkData.source_name} · Started ${new Date(networkData.at).toLocaleString()} · Results are a snapshot, not continuous monitoring.`;
 $('#network-summary').innerHTML=[['all','Total Devices','⌖'],['workstation','Workstations','▣'],['server','Servers','▤'],['printer','Printers','▥'],['phone','Phones','▯'],['network','Network Devices','⌘']].map(([type,label,icon])=>`<div class="network-total ${type}"><span aria-hidden="true">${icon}</span><strong>${type==='all'?rows.length:rows.filter(d=>d.type===type).length}</strong><small>${label}</small></div>`).join('');
 $('#network-type-tabs').innerHTML=[['all','All'],...Object.entries(networkTypes)].map(([type,label])=>`<button data-network-type="${type}" class="${networkFilter===type?'active':''}" aria-pressed="${networkFilter===type}">${label} <span>${type==='all'?rows.length:rows.filter(d=>d.type===type).length}</span></button>`).join('');bind('[data-network-type]',b=>{networkFilter=b.dataset.networkType;renderNetwork();});
 const filtered=rows.filter(d=>networkFilter==='all'||d.type===networkFilter);$('#network-device-list').hidden=networkMap;$('#network-map').hidden=!networkMap;$('#network-list-view').classList.toggle('active',!networkMap);$('#network-map-view').classList.toggle('active',networkMap);
 $('#network-device-list').innerHTML='<table><thead><tr><th>DEVICE / HOSTNAME</th><th>IP ADDRESS</th><th>MAC ADDRESS</th><th>TYPE</th><th>OS</th><th>OPEN TCP PORTS</th><th>PING</th><th>OBSERVATION</th><th>ACTION</th></tr></thead><tbody>'+filtered.map(d=>`<tr><td><strong>${escape(d.name)}</strong>${d.scanner?'<small>Scan agent</small>':''}</td><td><code>${escape(d.ip)}</code></td><td><code>${escape(d.mac||'Not reported')}</code></td><td><span class="network-kind">${networkTypes[d.type]}</span></td><td>${escape(d.os||'Not reported')}</td><td>${d.ports.map(p=>`<span class="network-port">${p}</span>`).join(' ')||'—'}</td><td>${d.ping&&d.latency!==null?d.latency+' ms':'—'}</td><td><span class="${d.responding?'network-responding':'network-neighbor'}">${d.responding?'Responding':'Neighbor only'}</span></td><td><div class="network-row-actions"><button data-network-label="${escape(d.ip)}">Edit label</button>${['workstation','server','unknown'].includes(d.type)?`<button data-network-enroll="${escape(d.ip)}">＋ Add to RMM…</button>`:''}</div></td></tr>`).join('')+'</tbody></table>'+(filtered.length?'':'<p class="empty">No matching discovered devices.</p>');
 $('#network-map').innerHTML='<p class="muted">Discovery view of observed IPs. Physical links, routers, and network topology are not verified.</p><div class="network-map-grid">'+filtered.map(d=>`<div><span aria-hidden="true">⌖</span><strong>${escape(d.name==='Not reported'?d.ip:d.name)}</strong><p>${escape(d.ip)} · ${networkTypes[d.type]}</p><small>${d.responding?'Responding':'Neighbor only'}</small></div>`).join('')+'</div>';
 bind('[data-network-label]',b=>networkLabel(b.dataset.networkLabel));bind('[data-network-enroll]',b=>{message('Install the company agent manually on '+b.dataset.networkEnroll+'. Discovery does not install it.');enroll(networkData.company_id,networkData.location_id);});renderNetworkAgents();}
function networkLabel(ip){const d=networkRows().find(d=>d.ip===ip);showDialog(`<h2>Label discovered device</h2><p>${escape(ip)}</p><form id="network-label-form"><input name="scanId" type="hidden" value="${escape(networkData.id)}"><input name="ip" type="hidden" value="${escape(ip)}"><label>Device / hostname<input name="hostname" maxlength="120" value="${escape(d.name==='Not reported'?'':d.name)}"></label><label>Device type<select name="type">${Object.entries(networkTypes).map(([id,name])=>`<option value="${id}" ${id===d.type?'selected':''}>${name}</option>`).join('')}</select></label><p class="muted">Manual label for this scan result. It does not verify the device’s identity or operating system.</p>${actions('Save label')}</form>`);submitForm('#network-label-form','network-label',()=>loadNetwork(networkData.id));}
$('#network-site').onchange=()=>{try{localStorage.setItem('skybase-network-site',$('#network-site').value);}catch{}$('#network-cidr').value='';networkData={status:'empty',result:[],labels:[]};renderNetworkAgents();loadNetwork();};$('#network-list-view').onclick=()=>{networkMap=false;renderNetwork();};$('#network-map-view').onclick=()=>{networkMap=true;renderNetwork();};$('#network-refresh').onclick=()=>loadNetwork(networkData.id||'');
$('#network-scan-form').onsubmit=async e=>{e.preventDefault();networkStarting=true;renderNetworkAgents();$('#network-message').textContent='Starting scan…';try{const value=await api('network-scan',Object.fromEntries(new FormData(e.target)));$('#network-message').textContent='';await loadNetwork(value.id);}catch(error){$('#network-message').textContent=error.message;}finally{networkStarting=false;renderNetworkAgents();}};
let patchData={patches:[],rollouts:[],notifications:[],jobs:[]},patchLoading=false,patchCategory='all';
async function loadPatches(){if(patchLoading)return;patchLoading=true;try{patchData=await api('patches');renderPatches();}catch(error){$('#patch-message').textContent=error.message;}finally{patchLoading=false;}}
function renderPatches(){const query=$('#patch-search').value.toLowerCase();$('#patch-list').innerHTML=patchData.patches.filter(p=>(patchCategory==='all'||p.category===patchCategory)&&`${p.title} ${p.reference||''} ${p.description} ${p.vendor}`.toLowerCase().includes(query)).map(p=>`<article class="patch-card"><div class="patch-card-main"><div class="patch-card-title"><strong>${escape(p.title)}</strong><span class="patch-tag ${p.category}">${escape(p.category)}</span><span class="patch-tag severity-${p.severity}">${escape(p.severity)}</span>${p.reboot_required?'<span class="patch-tag reboot">Reboot required</span>':''}</div><p>${escape(p.description)}</p><p class="patch-facts">${p.reference?`Patch ID: <strong>${escape(p.reference)}</strong> · `:''}Vendor: <strong>${escape(p.vendor)}</strong> · Size: <strong>${p.size_mb===null?'Not specified':p.size_mb+' MB'}</strong> · Released: <strong>${p.released_at?escape(p.released_at):'Not specified'}</strong></p><p class="patch-counts">✓ Installed: <strong>Not verified</strong> <span>◷ Planned: <strong>${patchData.rollouts.filter(r=>r.patch_id===p.id).length}</strong></span></p></div><div class="patch-actions">${patchData.jobs?.find(j=>j.patch_id===p.id)?`<button data-patch-job="${escape(patchData.jobs.find(j=>j.patch_id===p.id).id)}">View notices</button>`:''}<button data-patch-notify="${escape(p.id)}">♧ Notify user</button><button class="primary" data-patch-deploy="${escape(p.id)}">➤ Deploy…</button><button data-patch-edit="${escape(p.id)}">✎ Edit</button><button class="danger" data-patch-delete="${escape(p.id)}">Delete</button></div></article>`).join('')||'<p class="empty">No matching patches. Add a vendor update to start your catalog.</p>';bind('[data-patch-edit]',b=>patchForm(b.dataset.patchEdit));bind('[data-patch-delete]',b=>deletePatch(b.dataset.patchDelete));bind('[data-patch-deploy]',b=>planPatch(b.dataset.patchDeploy));bind('[data-patch-notify]',b=>notifyPatch(b.dataset.patchNotify));bind('[data-patch-job]',b=>showPatchNoticeJob(b.dataset.patchJob));}
function patchForm(id=''){const p=patchData.patches.find(p=>p.id===id)||{};showDialog(`<div class="patch-dialog-heading"><h2>${id?'Edit Patch':'Add New Patch'}</h2><button class="patch-dialog-close" type="button" data-close aria-label="Close patch form">×</button></div><form id="patch-form"><input name="id" type="hidden" value="${escape(id)}"><div class="patch-form-grid"><label>Patch Name<input name="title" required maxlength="160" placeholder="Windows security update" value="${escape(p.title)}"></label><label>Patch ID<input name="reference" maxlength="120" placeholder="KB number or vendor reference" value="${escape(p.reference)}"></label><label class="patch-form-wide">Description<textarea name="description" maxlength="1000" placeholder="Security update for Windows…">${escape(p.description)}</textarea></label><label>Type<select name="category">${['security','critical','feature','driver','other'].map(v=>`<option value="${v}" ${v===(p.category||'security')?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label><label>Severity<select name="severity">${['critical','important','moderate','low'].map(v=>`<option value="${v}" ${v===(p.severity||'moderate')?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label><label>Vendor<input name="vendor" required maxlength="120" placeholder="Microsoft" value="${escape(p.vendor)}"></label><label>Release Date<input name="releasedAt" type="date" value="${escape(p.released_at)}"></label><label>Size (MB)<input name="sizeMb" type="number" min="0" max="1000000" step="any" placeholder="125.5" value="${p.size_mb??''}"></label><label class="patch-reboot-check"><input type="hidden" name="rebootRequired" value="no"><input name="rebootRequired" type="checkbox" value="yes" ${p.reboot_required?'checked':''}> Requires Reboot</label></div><details class="patch-form-advanced"><summary>Vendor information link (optional)</summary><label>Official vendor page<input name="sourceUrl" type="url" maxlength="1000" value="${escape(p.source_url)}" placeholder="https://vendor.example/update-information"></label></details><p id="form-error" role="alert"></p><button class="primary patch-form-submit" type="submit">${id?'Save Changes':'Add Patch'}</button></form>`);submitForm('#patch-form','patch-save',loadPatches);}

function deletePatch(id){const p=patchData.patches.find(p=>p.id===id);showDialog(`<h2>Delete patch</h2><p>Remove ${escape(p.title)} and its planned rollouts from the catalog?</p><p class="muted">Installed software on computers is unchanged.</p><p id="patch-delete-error" role="alert"></p><div class="actions"><button data-close>Cancel</button><button id="confirm-patch-delete" class="danger">Delete patch</button></div>`);$('#confirm-patch-delete').onclick=async()=>{const b=$('#confirm-patch-delete');b.disabled=true;try{await api('patch-delete',{id,confirm:true});$('#modal').close();await loadPatches();}catch(error){$('#patch-delete-error').textContent=error.message;b.disabled=false;}};}
function planPatch(id){const p=patchData.patches.find(p=>p.id===id);showDialog(`<h2>Plan deployment and notify company</h2><p><strong>${escape(p.title)}</strong></p><p class="muted">Saves a rollout plan and sends an advance popup to active signed-in users on the company’s online Windows computers. Offline computers are reported separately. Automatic patch installation is not connected; no update or restart is started.</p>${p.source_url?`<a href="${escape(p.source_url)}" target="_blank" rel="noopener noreferrer">Open vendor information ↗</a>`:''}<form id="patch-plan-form"><label>Company<select name="companyId" required>${options(inventory.companies,'','Select company')}</select></label><label>Maintenance window (include time zone)<input name="windowText" required minlength="3" maxlength="120" placeholder="Today, 6–7 PM Central"></label><p class="patch-notice-preview">${p.reboot_required?'The popup says a restart is expected after installation.':'The popup says no restart is planned, based on your patch settings.'} Users will be told this is advance notice of a planned update.</p>${actions('Save plan & notify company')}</form>`);const form=$('#patch-plan-form');form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('.primary');b.disabled=true;$('#form-error').textContent='Preparing company notices…';try{const result=await api('patch-plan',{patchId:id,companyId:form.elements.companyId.value,windowText:form.elements.windowText.value,notify:true,confirm:true});$('#modal').close();await loadPatches();showPatchNoticeJob(result.jobId);}catch(error){$('#form-error').textContent=error.message;b.disabled=false;}};}
async function showPatchNoticeJob(id){showDialog('<h2>Company notification results</h2><p class="muted">This tracks advance notices only. Updates are not installed and computers are not restarted.</p><div id="company-notice-results">Loading…</div><div class="actions"><button data-close>Close</button></div>');
 const poll=async()=>{if(!$('#modal').open||!$('#company-notice-results'))return;try{const job=await api('patch-notice-job?id='+encodeURIComponent(id));if(!$('#company-notice-results'))return;$('#company-notice-results').innerHTML=`<p>${job.status==='running'?'Sending company notices…':'Notification job complete.'}</p>`+job.targets.map(t=>`<div class="priority-item"><div><strong>${escape(t.name)} · ${escape(t.status)}</strong><p>${escape(t.detail)}</p></div></div>`).join('');if(job.status==='running')setTimeout(poll,1500);}catch(error){if($('#company-notice-results'))$('#company-notice-results').textContent=error.message;}};await poll();
}

function notifyPatch(id){const p=patchData.patches.find(p=>p.id===id),planned=inventory.devices.filter(d=>d.online&&d.windows&&patchData.rollouts.some(r=>r.patch_id===id&&r.node_id===d.id));
 showDialog(`<h2>Notify user about planned update</h2><p><strong>${escape(p.title)}</strong></p><p class="muted">Sends a Windows message to signed-in sessions on one online computer. The notice uses the catalog’s reboot setting. It does not install an update or restart the computer.</p><form id="patch-notify-form"><label>Computer<select name="nodeId" required>${options(planned.map(d=>({id:d.id,name:d.company+' / '+d.name})),'','Select planned online Windows computer')}</select></label><label>Maintenance window (include time zone)<input name="windowText" required minlength="3" maxlength="120" placeholder="Tomorrow, 6–7 PM Central"></label><p id="patch-notice-preview" class="patch-notice-preview"></p><p id="patch-notice-last" class="muted"></p>${actions('Send notification')}</form>`);
 const form=$('#patch-notify-form'),button=form.querySelector('.primary');if(!planned.length){$('#form-error').textContent='Save a rollout plan and bring its Windows computer online first.';button.disabled=true;}
 const preview=()=>{const time=form.elements.windowText.value||'[maintenance window]';$('#patch-notice-preview').textContent=`SkyBase IT Solutions: Planned update: ${p.title}. Maintenance window: ${time}. ${p.reboot_required?'A restart is expected after installation (per the planned update). Please save your work.':'No restart is planned (per the update catalog); IT will advise if this changes.'} This is an advance notice, not confirmation that installation has started. Contact your IT support with questions.`;const last=patchData.notifications?.find(n=>n.patch_id===id&&n.node_id===form.elements.nodeId.value);$('#patch-notice-last').textContent=last?'Last Windows-accepted notice: '+new Date(last.at).toLocaleString()+'. User reading is not verified.':'';};form.elements.windowText.oninput=preview;form.elements.nodeId.onchange=preview;preview();
 form.onsubmit=async e=>{e.preventDefault();button.disabled=true;$('#form-error').textContent='Sending notice…';try{const result=await api('patch-notify',{patchId:id,nodeId:form.elements.nodeId.value,windowText:form.elements.windowText.value,confirm:true});$('#modal').close();await loadPatches();$('#patch-message').textContent=result.partial?'Windows accepted the notice for some user sessions; other sessions failed. User reading is not verified.':'Windows accepted the notification. This does not confirm that the user read it.';}catch(error){$('#form-error').textContent=error.message;button.disabled=false;}};
}
$('#add-patch').onclick=()=>patchForm();$('#patch-search').oninput=renderPatches;bind('[data-patch-category]',b=>{patchCategory=b.dataset.patchCategory;document.querySelectorAll('[data-patch-category]').forEach(tab=>{const active=tab.dataset.patchCategory===patchCategory;tab.classList.toggle('active',active);tab.setAttribute('aria-pressed',String(active));});renderPatches();});
const securityNames={bitdefender:'Bitdefender GravityZone MSP',defender:'Microsoft Defender for Business',acronis:'Acronis Cyber Protect'};
const securityRequirements={bitdefender:'Set up your GravityZone MSP account, customer companies, and endpoint agent. API credentials and device mapping are needed for SkyBase status and scan controls.',defender:'Set up each customer’s Microsoft tenant and Defender for Business licenses. Onboard endpoints and configure Microsoft Graph permissions and admin consent for each tenant.',acronis:'Enable the security features in the customer’s Acronis protection plan and install its agent. Backup authentication alone does not verify antivirus protection or connect security data.'};
let securityData={preferences:[],providers:[]},securityLoading=false;
async function loadSecurity(){if(securityLoading)return;securityLoading=true;try{securityData=await api('security');renderSecurity();}catch(error){$('#security-message').textContent=error.message;}finally{securityLoading=false;}}
function renderSecurity(){
 const assigned=inventory.companies.filter(c=>securityData.preferences.some(p=>p.company_id===c.id)).length;
 $('#security-summary').innerHTML=`<div><span>Companies with a provider selected</span><strong>${assigned}</strong></div><div><span>Computers in inventory</span><strong>${inventory.devices.length}</strong></div><div><span>Protection verification</span><strong>Not connected</strong></div>`;
 $('#security-providers').innerHTML=Object.entries(securityNames).map(([id,name])=>{const provider=securityData.providers.find(p=>p.id===id);return `<article class="security-provider-card"><span class="security-shield" aria-hidden="true">◇</span><h3>${name}</h3><span class="backup-badge">API setup required</span><p>${escape(securityRequirements[id])}</p><div class="actions"><button data-security-settings="${id}">Configure console</button>${provider?.consoleUrl?`<a class="button-link" href="${escape(provider.consoleUrl)}" target="_blank" rel="noopener noreferrer">Open console ↗</a>`:''}</div></article>`;}).join('');
 const query=$('#security-search').value.toLowerCase(),filter=$('#security-provider-filter').value;
 $('#security-computers').innerHTML=inventory.devices.filter(d=>{const provider=securityData.preferences.find(p=>p.company_id===d.companyId)?.provider;return (!filter||(filter==='unassigned'?!provider:provider===filter))&&`${d.name} ${d.company}`.toLowerCase().includes(query);}).map(d=>{const id=securityData.preferences.find(p=>p.company_id===d.companyId)?.provider,provider=securityData.providers.find(p=>p.id===id);return `<article class="antivirus-card"><div class="antivirus-card-heading"><span class="antivirus-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z"/></svg></span><div><strong>${escape(d.name)}</strong><p>${securityNames[id]||'No provider selected'}</p></div><span class="antivirus-status">${id?'Not verified':'Not selected'}</span></div><div class="antivirus-facts"><div><span>Version:</span><strong>Not verified</strong></div><div><span>Last Update:</span><strong>Not verified</strong></div><div><span>Company:</span><strong>${escape(d.company)}</strong></div></div><p class="antivirus-warning">⚠ ${id?'Provider connection required':'Choose a security provider'}</p><div class="antivirus-actions"><button data-security-company="${escape(d.companyId)}">✎ Edit provider</button><button class="danger" data-security-remove="${escape(d.companyId)}" ${!id?'disabled':''}>Remove choice</button></div>${provider?.consoleUrl?`<a class="antivirus-console-link" href="${escape(provider.consoleUrl)}" target="_blank" rel="noopener noreferrer">Manage in provider console ↗</a>`:''}</article>`;}).join('')||'<p class="empty">No matching computers.</p>';
 bind('[data-security-settings]',b=>securityConsole(b.dataset.securitySettings));bind('[data-security-company]',b=>assignSecurity(b.dataset.securityCompany));bind('[data-security-remove]',b=>removeSecurityChoice(b.dataset.securityRemove));
}
function securityConsole(provider){const current=securityData.providers.find(p=>p.id===provider);showDialog(`<h2>${securityNames[provider]}</h2><p class="muted">${escape(securityRequirements[provider])}</p><form id="security-console-form"><input name="provider" type="hidden" value="${provider}"><label>Management console URL<input name="consoleUrl" type="url" maxlength="1000" value="${escape(current?.consoleUrl||'')}" placeholder="https://your-provider-console.example"></label><p class="muted">Saves a console link only. Enter API credentials through server configuration when integration is available; do not enter secrets here.</p>${actions('Save console link')}</form>`);submitForm('#security-console-form','security-settings',loadSecurity);}
function assignSecurity(companyId=''){showDialog(`<h2>Choose company security provider</h2><form id="security-provider-form"><label>Company<select name="companyId" required>${options(inventory.companies,companyId,'Select company')}</select></label><label>Primary security provider<select name="provider"><option value="">Not selected</option>${Object.entries(securityNames).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><p class="muted">This saves a company preference only. It does not deploy agents, change protection policies, or remove existing antivirus.</p>${actions('Save provider')}</form>`);const form=$('#security-provider-form');const update=()=>form.elements.provider.value=securityData.preferences.find(p=>p.company_id===form.elements.companyId.value)?.provider||'';form.elements.companyId.onchange=update;update();submitForm('#security-provider-form','security-provider',loadSecurity);}
function removeSecurityChoice(companyId){const company=inventory.companies.find(c=>c.id===companyId);showDialog(`<h2>Remove company provider choice</h2><p>Clear the security provider selection for <strong>${escape(company?.name)}</strong> and all its computer cards?</p><p class="muted">This only removes the saved SkyBase choice. Antivirus agents, policies, and subscriptions remain in place.</p><p id="security-remove-error" role="alert"></p><div class="actions"><button data-close>Cancel</button><button class="danger" id="confirm-security-remove">Remove choice</button></div>`);$('#confirm-security-remove').onclick=async()=>{const b=$('#confirm-security-remove');b.disabled=true;try{await api('security-provider',{companyId,provider:''});$('#modal').close();await loadSecurity();}catch(error){$('#security-remove-error').textContent=error.message;b.disabled=false;}};}
function installAntivirus(){showDialog(`<h2>Install antivirus</h2><p class="muted">Installation currently runs through the provider’s console. SkyBase does not deploy security agents yet.</p><label>Company<select id="antivirus-install-company">${options(inventory.companies,'','Select company')}</select></label><div id="antivirus-install-guide"></div><div class="actions"><button data-close>Close</button></div>`);$('#antivirus-install-company').onchange=()=>{const id=securityData.preferences.find(p=>p.company_id===$('#antivirus-install-company').value)?.provider,provider=securityData.providers.find(p=>p.id===id);$('#antivirus-install-guide').innerHTML=id?`<h3>${securityNames[id]}</h3><p>${escape(securityRequirements[id])}</p><p>Use the correct customer’s deployment or onboarding package from the provider console, then confirm protection there.</p>${provider?.consoleUrl?`<a class="button-link primary" href="${escape(provider.consoleUrl)}" target="_blank" rel="noopener noreferrer">Open ${securityNames[id]} ↗</a>`:'<p class="muted">Configure the provider console link under Provider setup first.</p>'}`:'<p class="muted">Choose a company with a saved security provider to continue.</p>';};}
$('#install-antivirus').onclick=installAntivirus;
$('#assign-security-provider').onclick=()=>assignSecurity();$('#security-search').oninput=renderSecurity;$('#security-provider-filter').onchange=renderSecurity;
$('#backup-search').oninput=renderBackups;$('#backup-company').onchange=renderBackups;$('#backup-history-filter').onchange=renderBackups;
function linkAcronis(id){
  const d=inventory.devices.find(d=>d.id===id),link=acronisData.links.find(l=>l.node_id===id);
  showDialog(`<h2>Link Acronis device</h2><p class="muted">${escape(d.name)} · ${escape(d.company)}. Confirm the correct customer and computer before saving.</p><form id="acronis-link-form"><input type="hidden" name="nodeId" value="${escape(id)}"><label>Acronis resource<select name="resourceId">${options(acronisData.resources.map(r=>({id:r.id,name:r.tenant+' / '+r.name+' / '+r.type})),link?.resource_id,'Not linked')}</select></label><p class="muted">This links existing records; it does not create a backup plan or deploy an agent.</p>${actions('Save link')}</form>`);submitForm('#acronis-link-form','acronis-link',loadAcronis);
}
$('#acronis-connect').onclick=async()=>{const b=$('#acronis-connect');b.disabled=true;$('#acronis-status').textContent='Checking Acronis authentication…';try{renderAcronis(await api('acronis-connect',{}));}catch(error){$('#acronis-console').hidden=true;$('#acronis-status').textContent=error.message;}finally{b.disabled=false;}};
$('#modal').addEventListener('close',()=>$('#modal').classList.remove('wide'));
$('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('login',Object.fromEntries(new FormData(e.target)));e.target.reset();message('');await refresh();}catch(error){message(error.message);}finally{b.disabled=false;}};
$('#logout').onclick=async()=>{try{await api('logout',{});$('#modal').close();$('#workspace').hidden=true;$('#logout').hidden=true;$('#login').hidden=false;}catch(error){message(error.message);}};
$('#sync').onclick=async()=>{$('#sync').disabled=true;try{await api('sync',{});message('');}catch(error){message(error.message);}finally{await refresh();$('#sync').disabled=false;}};
$('#search').oninput=render;['#company-filter','#location-filter','#group-filter','#status-filter'].forEach(id=>$(id).onchange=render);
$('#add-customer').onclick=()=>customerForm();$('#cards-add-customer').onclick=()=>customerForm();$('#cards-add-company').onclick=()=>companyForm();
$('#global-search').oninput=()=>{$('#search').value=$('#global-search').value;changePage('devices',true);render();};
$('#global-company').onchange=()=>{$('#company-filter').value=$('#global-company').value;$('#backup-company').value=$('#global-company').value;render();if(page==='backups')renderBackups();};
$('#view-all-computers').onclick=()=>changePage('devices',true);$('#quick-remote').onclick=()=>changePage('devices',true);
$('#customize-dashboard').onclick=customizeDashboard;$('#quick-device').onclick=()=>enroll();$('#quick-company').onclick=companyForm;$('#quick-backups').onclick=()=>changePage('backups',true);
$('#add-company').onclick=companyForm;$('#add-device').onclick=()=>enroll($('#company-filter').value,$('#location-filter').value,$('#group-filter').value);$('#add-location').onclick=()=>locationForm();$('#add-group').onclick=()=>groupForm();bind('[data-page]',b=>changePage(b.dataset.page,true));
window.addEventListener('popstate',()=>changePage(pageFromUrl()));
window.addEventListener('hashchange',()=>changePage(pageFromUrl()));
await refresh();setInterval(()=>{if(!$('#workspace').hidden)refresh();},30000);
